  @doc """
  table_event_max_bits/0 in bytes, rounded up to the family 8-byte write-buffer
  granularity.
  """
  @spec table_event_max_bytes() :: pos_integer()
  def table_event_max_bytes, do: 8

  @doc """
  The debug/log/tooling name of a TableEventType value, by atom or by wire
  value; anything past the named variants names as "???".
  """
  @spec enum_name_table_event_type(Benchtable.TableEventType.t() | integer()) :: String.t()
  def enum_name_table_event_type(value) do
    case value do
      :none -> "None"
      0 -> "None"
      :hit -> "Hit"
      1 -> "Hit"
      :chat -> "Chat"
      2 -> "Chat"
      :pickup -> "Pickup"
      3 -> "Pickup"
      _ -> "???"
    end
  end

  @doc "The §5 zero form of TableEvent: the empty union, None."
  @spec zero_table_event() :: Benchtable.TableEvent.t()
  def zero_table_event, do: nil

  @doc """
  Packs a TableEvent into a fresh binary and returns the wire bytes. The
  writer trusts the caller up to the O(1) contract checks, which raise
  ArgumentError — always on, since the BEAM has no compile-out assert.
  """
  @spec write_table_event!(Benchtable.TableEvent.t()) :: binary()
  def write_table_event!(value) do
    v =
      case value do
        nil ->
          0

        {:hit, _} ->
          1

        {:chat, _} ->
          2

        {:pickup, _} ->
          3

        value_other ->
          raise ArgumentError, "value is not a TableEvent value: #{inspect(value_other)}"
      end

    scratch = v
    data = <<>>

    {data, scratch, scratch_bits} =
      case value do
        {:hit, value_hit} ->
          %{
            target_id: value_hit_target_id,
            damage: value_hit_damage,
            hit_kind: value_hit_hit_kind,
            crit: value_hit_crit
          } = value_hit

          v = value_hit_target_id &&& 0xFFF
          scratch = scratch ||| v <<< 2

          if value_hit_damage < 0 do
            raise ArgumentError, "value.hit.damage is below the wire minimum"
          end

          if value_hit_damage > 4095 do
            raise ArgumentError, "value.hit.damage is above the wire maximum"
          end

          v = value_hit_damage
          scratch = scratch ||| v <<< 14

          if value_hit_hit_kind < 0 do
            raise ArgumentError, "value.hit.hit_kind is below the wire minimum"
          end

          if value_hit_hit_kind > 7 do
            raise ArgumentError, "value.hit.hit_kind is above the wire maximum"
          end

          v = value_hit_hit_kind
          scratch = scratch ||| v <<< 26
          v = if value_hit_crit, do: 1, else: 0
          scratch = scratch ||| v <<< 29
          data = <<data::binary, scratch::little-size(3)-unit(8)>>
          scratch = scratch >>> 24
          scratch_bits = 6
          {data, scratch, scratch_bits}

        {:chat, value_chat} ->
          %{channel: value_chat_channel, speaker: value_chat_speaker} = value_chat

          if value_chat_channel < 0 do
            raise ArgumentError, "value.chat.channel is below the wire minimum"
          end

          if value_chat_channel > 3 do
            raise ArgumentError, "value.chat.channel is above the wire maximum"
          end

          v = value_chat_channel
          scratch = scratch ||| v <<< 2
          v = value_chat_speaker &&& 0xFFF
          scratch = scratch ||| v <<< 4
          data = <<data::binary, scratch::little-size(2)-unit(8)>>
          scratch_bits = 0
          scratch = 0
          {data, scratch, scratch_bits}

        {:pickup, value_pickup} ->
          %{item_id: value_pickup_item_id, amount: value_pickup_amount} = value_pickup
          v = value_pickup_item_id &&& 0x3FF
          scratch = scratch ||| v <<< 2

          if value_pickup_amount < 0 do
            raise ArgumentError, "value.pickup.amount is below the wire minimum"
          end

          if value_pickup_amount > 255 do
            raise ArgumentError, "value.pickup.amount is above the wire maximum"
          end

          v = value_pickup_amount
          scratch = scratch ||| v <<< 12
          data = <<data::binary, scratch::little-size(2)-unit(8)>>
          scratch = scratch >>> 16
          scratch_bits = 4
          {data, scratch, scratch_bits}

        _ ->
          # None, or an arm whose tag is its whole wire (SPEC §4.8)
          scratch_bits = 2
          {data, scratch, scratch_bits}
      end

    if scratch_bits != 0, do: <<data::binary, scratch>>, else: data
  end

  @doc """
  write_table_event!/1 as a verdict: `{:ok, binary}`, or `{:error, message}`
  where the bang form raises ArgumentError.
  """
  @spec write_table_event(Benchtable.TableEvent.t()) :: {:ok, binary()} | {:error, String.t()}
  def write_table_event(value) do
    {:ok, write_table_event!(value)}
  rescue
    e in ArgumentError -> {:error, Exception.message(e)}
  end

  @doc """
  Decodes a TableEvent from the first num_bits of data and REPORTS THE BITS
  CONSUMED (SPEC §5): `{:ok, value, bits_read}`. The count is what frames a
  second object behind the first in one buffer. `:error` rejects the wire
  (bounds, ranges, wire constants, padding); hostile bytes never raise. No
  slack past the payload is required.
  """
  @spec read_table_event_bits(binary(), non_neg_integer()) ::
          {:ok, Benchtable.TableEvent.t(), non_neg_integer()} | :error
  def read_table_event_bits(data, num_bits) when is_binary(data) and is_integer(num_bits) do
    try do
      if num_bits > byte_size(data) * 8 do
        # the payload cannot exceed the buffer behind it
        throw(:invalid)
      end

      if 2 > num_bits, do: throw(:invalid)
      rv = rdw(data, 0, 49)
      v = rv &&& 0x3
      bits_read = 2

      {bits_read, v} =
        case v do
          1 ->
            if 30 > num_bits, do: throw(:invalid)
            rv = rd(data, 2, 28)
            v = rv &&& 0xFFF
            v_hit_target_id = v
            v = rv >>> 12 &&& 0xFFF
            v_hit_damage = v
            v = rv >>> 24 &&& 0x7
            v_hit_hit_kind = v
            v = rv >>> 27
            v_hit_crit = v == 1

            v_hit = %Benchtable.TableHitEvent{
              target_id: v_hit_target_id,
              damage: v_hit_damage,
              hit_kind: v_hit_hit_kind,
              crit: v_hit_crit
            }

            bits_read = 30
            {bits_read, {:hit, v_hit}}

          2 ->
            if 16 > num_bits, do: throw(:invalid)
            rv = rd(data, 2, 14)
            v = rv &&& 0x3
            v_chat_channel = v
            v = rv >>> 2
            v_chat_speaker = v
            v_chat = %Benchtable.TableChatEvent{channel: v_chat_channel, speaker: v_chat_speaker}
            bits_read = 16
            {bits_read, {:chat, v_chat}}

          3 ->
            if 20 > num_bits, do: throw(:invalid)
            rv = rd(data, 2, 18)
            v = rv &&& 0x3FF
            v_pickup_item_id = v
            v = rv >>> 10
            v_pickup_amount = v

            v_pickup = %Benchtable.TablePickupEvent{
              item_id: v_pickup_item_id,
              amount: v_pickup_amount
            }

            bits_read = 20
            {bits_read, {:pickup, v_pickup}}

          _ ->
            # None — the tag is the whole wire (SPEC §4.8)
            {bits_read, nil}
        end

      {:ok, v, bits_read}
    catch
      :invalid -> :error
    end
  end

  @doc """
  Decodes a TableEvent from the first num_bits of data: read_table_event_bits/2
  with the count dropped, the family read verdict.
  """
  @spec read_table_event(binary(), non_neg_integer()) :: {:ok, Benchtable.TableEvent.t()} | :error
  def read_table_event(data, num_bits) when is_binary(data) and is_integer(num_bits) do
    case read_table_event_bits(data, num_bits) do
      {:ok, value, _bits_read} -> {:ok, value}
      :error -> :error
    end
  end
end
